#!/usr/bin/env python3
"""Write site/examples-code.soil from the example sources."""
import json
from pathlib import Path

root = Path(__file__).resolve().parent.parent
items = []
for path in sorted((root / "examples" / "ui").glob("*.soil")):
    if path.name == "prelude.soil":
        continue
    items.append((path.stem, path.read_text()))

lines = [
    "; SPDX-License-Identifier: MIT OR Apache-2.0",
    "; Generated by site/gen-examples.py. Do not edit.",
    "(defconst example-code",
    "  (list",
]
for slug, code in items:
    lines.append(f"    (list (list :slug {json.dumps(slug)}) (list :code {json.dumps(code)}))")
lines += ["  ))", ""]
(root / "site" / "examples-code.soil").write_text("\n".join(lines))
